begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(1468526948026900)
,p_name=>'ADMISSION_REPORT_HTML_CSS'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select admission_id, first_name||'' ''||last_name student_name,',
'            f_class_name(CLASS_ID) class,',
'            to_char(ADMISSION_DATE,''dd-Mon-rrrr'') ADMISSION_DATE',
'     from   admission',
'     order  by admission_id'))
,p_report_layout_id=>wwv_flow_imp.id(3744579806007465)
,p_format=>'PDF'
,p_output_file_name=>'ADMISSION_REPORT_HTML_CSS'
,p_content_disposition=>'ATTACHMENT'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(3744965094008511)
,p_shared_query_id=>wwv_flow_imp.id(1468526948026900)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select admission_id, first_name||'' ''||last_name student_name,',
'            f_class_name(CLASS_ID) class,',
'            to_char(ADMISSION_DATE,''dd-Mon-rrrr'') ADMISSION_DATE',
'     from   admission',
'     order  by admission_id'))
);
end;
