prompt --application/shared_components/reports/report_queries/student_session_wise_fee
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(3653169112787107)
,p_name=>'student_session_wise_fee'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select student_id||'' - ''||f_st_std_name(student_id) name, sessions, f_class_name(class_id) class, ',
'       f_fee_amt_month(fd.fee_amount_d_id) month, to_char(collection_date, ''DD-Mon-RRRR'') cdate, ',
'       fd.monthly_Fee, fd.bi_annual_fee, fd.annual_fee,',
'       total',
'from   fee_m fm, fee_d fd, fee_amount_d fad',
'where  fd.fee_m_id = fm.fee_m_id ',
'and    fd.fee_amount_d_id = fad.fee_amount_d_id',
'order  by month_id'))
,p_report_layout_id=>wwv_flow_imp.id(3742193992944072)
,p_format=>'PDF'
,p_output_file_name=>'student_session_wise_fee'
,p_content_disposition=>'ATTACHMENT'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(3742717053945291)
,p_shared_query_id=>wwv_flow_imp.id(3653169112787107)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select student_id||'' - ''||f_st_std_name(student_id) name, sessions, f_class_name(class_id) class, ',
'       f_fee_amt_month(fd.fee_amount_d_id) month, to_char(collection_date, ''DD-Mon-RRRR'') cdate, ',
'       fd.monthly_Fee, fd.bi_annual_fee, fd.annual_fee,',
'       total',
'from   fee_m fm, fee_d fd, fee_amount_d fad',
'where  fd.fee_m_id = fm.fee_m_id ',
'and    fd.fee_amount_d_id = fad.fee_amount_d_id',
'and    student_id like nvl(:P3339_STUDENT_ID, 0)',
'and    sessions   like nvl(:P3339_SESSIONS, 0) ',
'order  by month_id'))
);
end;
/
prompt --application/shared_components/reports/report_queries/class_session_wise_fee
begin
wwv_flow_imp_shared.create_shared_query(
 p_id=>wwv_flow_imp.id(3676835726025282)
,p_name=>'class_session_wise_fee'
,p_query_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(fm.class_id) class, sessions, s.student_id||'' - ''||f_st_std_name(s.student_id) student, ',
'       sum(nvl(total,0)) collected, f_total_fee_cls(fm.class_id) total_for_class, ',
'       (f_total_fee_cls(fm.class_id) - sum(nvl(total,0))) Unpaid',
'from   fee_m fm, fee_d fd, student s',
'where  s.student_id = fm.student_id(+)',
'and    fd.fee_m_id = fm.fee_m_id',
'and    fm.class_id = :P3040_CLASS',
'and    fm.sessions = :P3040_SESSIONS',
'group  by f_class_name(fm.class_id), sessions, s.student_id, f_total_fee_cls(fm.class_id)',
'order  by class'))
,p_report_layout_id=>wwv_flow_imp.id(3743898761993285)
,p_format=>'PDF'
,p_output_file_name=>'class_session_wise_fee'
,p_content_disposition=>'ATTACHMENT'
);
wwv_flow_imp_shared.create_shared_query_stmnt(
 p_id=>wwv_flow_imp.id(3744230402994291)
,p_shared_query_id=>wwv_flow_imp.id(3676835726025282)
,p_sql_statement=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(fm.class_id) class, sessions, s.student_id||'' - ''||f_st_std_name(s.student_id) student, ',
'       sum(nvl(total,0)) collected, f_total_fee_cls(fm.class_id) total_for_class, ',
'       (f_total_fee_cls(fm.class_id) - sum(nvl(total,0))) Unpaid',
'from   fee_m fm, fee_d fd, student s',
'where  s.student_id = fm.student_id(+)',
'and    fd.fee_m_id = fm.fee_m_id',
'and    fm.class_id = :P3040_CLASS',
'and    fm.sessions = :P3040_SESSIONS',
'group  by f_class_name(fm.class_id), sessions, s.student_id, f_total_fee_cls(fm.class_id)',
'order  by class'))
);
end;
