prompt --application/shared_components/security/authentications/app_users
begin
wwv_flow_imp_shared.create_authentication(
 p_id=>wwv_flow_imp.id(78726993147760048114)
,p_name=>'App Users'
,p_scheme_type=>'NATIVE_CUSTOM'
,p_attribute_03=>'user_authentication'
,p_attribute_05=>'N'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION user_authentication ',
'(P_USERNAME USER_INFO.USERNAME%type,',
' P_PASSWORD USER_INFO.PASSWORD%type)',
'RETURN BOOLEAN ',
'is',
'v_user_info NUMBER := 0 ; ',
'BEGIN ',
'SELECT 1 ',
'INTO v_user_info ',
'FROM USER_INFO',
'WHERE UPPER(USERNAME) = UPPER(P_USERNAME) ',
'AND PASSWORD = P_PASSWORD ; ',
'RETURN TRUE; ',
'EXCEPTION ',
'WHEN NO_DATA_FOUND THEN ',
' RETURN FALSE; ',
'end;'))
,p_use_secure_cookie_yn=>'N'
,p_ras_mode=>0
);
end;
