,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' v_fee_amount_id fee_amount.fee_amount_id%type ;',
'',
' count_fee_amt number ;',
'begin',
' select count(fee_amount_id)',
' into   count_fee_amt',
' from   fee_amount',
' where  FEE_TYPE_ID = :P29_FEE_TYPE_ID',
' and    CLASS_ID    = :P29_CLASS_ID ;',
'',
' if count_fee_amt < 1 then',
'',
' select nvl(max(to_number(fee_amount_id)),0) + 1',
' into   v_fee_amount_id',
' from   fee_amount ;',
'',
'',
'insert into FEE_AMOUNT(fee_amount_id, FEE_TYPE_ID, CLASS_ID, FEE_AMOUNT, action_user )',
'values(v_fee_amount_id, :P29_FEE_TYPE_ID, :P29_CLASS_ID, :P29_FEE_AMOUNT, v(''APP_USER'')) ;',
'',
'',
'',
'end if ;',
'',
'exception',
'when others then null ;',
'end ;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1821074378236429
);
end;
