,p_plug_template=>wwv_flow_imp.id(73821458498215307568)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select f_class_name(atm.class_id) class_name, ',
'       f_section_name(atm.section_id) section_name, attendance_date, roll_number, first_name||'' ''||last_name, status, ad.student_id, (CASE WHEN Status = ''Absent'' THEN 1',
'                  ELSE 0',
'             END) Absent, (CASE WHEN Status = ''Present'' THEN 1',
'                  ELSE 0',
'             END) present',
'from   attendance_m atm, student s, attendance_d ad',
'where  atm.ATTENDANCE_M_ID like nvl(:p_ATTENDANCE_M_ID, ''%'')',
'and    atm.attendance_m_id = ad.attendance_m_id',
'and    ad.student_id = s.student_id (+)',
'and  atm.class_id like  nvl(:P51_CLASS, ''%'')  ',
'and  atm.section_id like nvl(:P51_SECTION, ''%'')',
'and   atm.attendance_date like :P51_ATTENDANCE_DATE',
'order  by  attendance_date desc  ;'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_page_header=>'Class wise Daily Attendance Report'
);
