'    case when coalesce(:P1045_CLASS_ID,''0'') = "CLASS_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'    (substr("CLASS_NAME", 1, 50)||( case when length("CLASS_NAME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    (substr("CLASS_DESCRIPTION", 1, 50)||( case when length("CLASS_DESCRIPTION") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "CLASS" x',
'where (:P1045_SEARCH is null',
'        or upper(x."CLASS_NAME") like ''%''||upper(:P1045_SEARCH)||''%''',
'        or upper(x."CLASS_DESCRIPTION") like ''%''||upper(:P1045_SEARCH)||''%''',
