wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2784215688379591)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'fetch data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' v_attendance_m_id attendance_m.attendance_m_id%type;',
' v_attendance_d_id attendance_d.attendance_d_id%type;',
'begin',
'',
' select nvl(max(to_number(ATTENDANCE_M_ID)),0) + 1',
' into   v_attendance_m_id',
' from   ATTENDANCE_M  ;',
'',
' select nvl(max(to_number(ATTENDANCE_D_ID)),0) + 1',
' into   v_attendance_d_id',
' from   ATTENDANCE_D  ;',
'',
'APEX_COLLECTION.CREATE_OR_TRUNCATE_COLLECTION(',
'              p_collection_name => ''SAMPLE_NAME'');',
'',
'for i in (SELECT s.student_id, ''Present'' status, v_attendance_m_id attendance_m_id, ',
'                 v_attendance_d_id attendance_d_id',
'          from   student s',
'          where  s.section_id = :P1054_SECTION',
'          and    s.class_id = :P1054_CLASS ',
'          order  by student_id )',
'',
'loop',
'',
'APEX_COLLECTION.ADD_MEMBER(',
'        p_collection_name => ''SAMPLE_NAME'' ,',
'        p_n001            => i.STUDENT_ID, ',
'        p_c001            => i.status,',
'        p_n002            => i.attendance_m_id,',
'        p_n003            => i.attendance_d_id',
'           ) ;',
'',
'end loop ; ',
'end ;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2777661341379554)
,p_internal_uid=>4389456780350326
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2783319393379585)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(11755210190966014)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Detail Section - Save Interactive Grid Data'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'',
'begin',
'',
'',
'  case :APEX$ROW_STATUS',
'    when ''U'' then',
'      APEX_COLLECTION.UPDATE_MEMBER(',
'         p_collection_name => ''SAMPLE_NAME'' ,',
'         p_seq             => :SL,',
'         p_n001            => :STUDENT_ID,',
'         p_c001            => :STATUS,',
'         p_n002            => :attendance_m_id,',
'         p_n003            => :attendance_d_id',
'               );',
'  end case ;',
'end ;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'N'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>4388560485350320
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2783781224379591)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save all'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' v_attendance_d_id attendance_d.attendance_d_id%type;',
'',
'',
'begin',
'',
' select nvl(max(to_number(ATTENDANCE_D_ID)),0) + 1',
' into   v_attendance_d_id',
' from   ATTENDANCE_D  ;',
'',
' insert into attendance_m(attendance_m_id, attendance_date, class_id, section_id, action_user)',
' values(:P1054_ATTENDANCE_M_ID, to_date(:P1054_DATE, ''DD-Mon-RRRR''), :P1054_CLASS, :P1054_SECTION, v(''APP_USER'')) ;',
'',
'insert into attendance_d(attendance_m_id, student_id, status, attendance_d_id)',
'(select                 n002, n001, c001, (v_attendance_d_id + Seq_id)',
'  from   apex_collections',
'  where  collection_name = ''SAMPLE_NAME''  ',
'     ) ;',
'     ',
'    APEX_COLLECTION.TRUNCATE_COLLECTION(',
'        p_collection_name => ''SAMPLE_NAME'' );',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2776975299379544)
,p_process_success_message=>'Saved Attendance Information'
,p_internal_uid=>4389022316350326
);
end;
