,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select "RESULT_M_ID",',
'    null LINK_CLASS,',
'    apex_page.get_url(p_items => ''P1063_RESULT_M_ID'', p_values => "RESULT_M_ID") LINK,',
'    null ICON_CLASS,',
'    null LINK_ATTR,',
'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P1063_RESULT_M_ID,''0'') = "RESULT_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'   -- (substr("ACTION_DATE_TIME", 1, 50)||( case when length("ACTION_DATE_TIME") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'    ''Exam ID - ''||Exam_m_id||'' - ''||f_subject_name(subject_id) LIST_TITLE,',
'   -- (substr("ACTION_DATE_TIME", 1, 50)||( case when length("ACTION_DATE_TIME") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'   (select to_char(exam_date, ''DD-Mon-RRRR'')',
'   from    exam_d',
'   where   exam_m_id = x.exam_m_id',
'   and     subject_id = x.subject_id) LIST_TEXT,',
'    null LIST_BADGE',
'from "RESULT_M" x',
'where (:P1063_SEARCH is null',
'        or upper(x."EXAM_M_ID") like ''%''||upper(:P1063_SEARCH)||''%''',
'        or upper(f_subject_name(subject_id)) like ''%''||upper(:P1063_SEARCH)||''%''',
'    )',
'order by "EXAM_M_ID" desc, subject_id desc'))
