'    null ICON_COLOR_CLASS,',
'    case when coalesce(:P1079_FEE_M_ID,''0'') = "FEE_M_ID"',
'      then ''is-active'' ',
'      else '' ''',
'    end LIST_CLASS,',
'   -- (substr("COLLECTION_DATE", 1, 50)||( case when length("COLLECTION_DATE") > 50 then ''...'' else '''' end )) LIST_TITLE,',
'      ''Fee ID: ''||fee_m_id||'' Date: ''||to_char(COLLECTION_DATE, ''DD-Mon-RRRR'') LIST_TITLE,',
'     f_st_std_name(student_id)||'' - ''||f_class_name(class_id) LIST_TEXT,',
'    --(substr("COLLECTION_DATE", 1, 50)||( case when length("COLLECTION_DATE") > 50 then ''...'' else '''' end )) LIST_TEXT,',
'    null LIST_BADGE',
'from "FEE_M" x',
'where collection_date between to_date(:P1079_FROM_DATE, ''DD-Mon-RRRR'') and to_date(:P1079_TO_DATE, ''DD-Mon-RRRR'')',
'order by "FEE_M_ID" desc'))
